#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
#include "memt.c" /* generated by make_memt.py */
#define N 200
static unsigned rs=1; static unsigned rnd(void){ rs=rs*1103515245+12345; return rs>>8; }
int main(void){
    void *p[N]={0}; size_t sz[N]={0}; unsigned char tag[N];
    for(int it=0; it<200000; it++){
        int i=rnd()%N; int op=rnd()%5;
        if(p[i]){ for(size_t k=0;k<sz[i];k++) if(((unsigned char*)p[i])[k]!=tag[i]){printf("CORRUPT it %d slot %d\n",it,i);return 1;} }
        if(op==0 && p[i]){ t_free(p[i]); p[i]=0; }
        else if(op==1 && p[i]){ /* shrink like save_state_alloc */ size_t ns = rnd()% (sz[i]+1); if(!ns) ns=1; void *q=t_realloc(p[i],ns); if(q!=p[i]){printf("shrink moved\n");return 1;} sz[i]=ns; }
        else if(op==2){ /* grab the largest block minus reserve, then shrink */
            if(p[i]) { t_free(p[i]); p[i]=0; }
            size_t tot; size_t l=mem_largest_free(&tot); if(l>0x4000 && rnd()%4==0){ size_t cap = l; p[i]=t_malloc(cap); if(!p[i]){printf("largest alloc failed\n");return 1;} sz[i]= rnd()%cap+1; memset(p[i],0x5A,sz[i]); p[i]=t_realloc(p[i],sz[i]); tag[i]=rnd(); memset(p[i],tag[i],sz[i]); }
        }
        else if(!p[i]){ sz[i]=rnd()%(rnd()%4==0?40000:300)+1; p[i]=t_malloc(sz[i]); if(!p[i]){sz[i]=0; continue;} tag[i]=rnd(); memset(p[i],tag[i],sz[i]); }
    }
    for(int i=0;i<N;i++) if(p[i]) t_free(p[i]);
    size_t tot; size_t l=mem_largest_free(&tot);
    printf("after freeing everything: largest %zx total %zx (heap0 %zx)\n", l, tot, sizeof(heap0_buf)-HDR_SIZE);
    return !(l==sizeof(heap0_buf)-HDR_SIZE);
}
